import{z as B,x as A,o as r,c as p,q as i,j as n,D as e,d as E,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"遗忘的度量","description":"","frontmatter":{"title":"遗忘的度量","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/forgetting-metrics.md","filePath":"llm/forgetting-metrics.md","lastUpdated":1791413859000}'),d={name:"llm/forgetting-metrics.md"};function m(D,a,h,g,f,F){const l=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="遗忘的度量" tabindex="-1">遗忘的度量 <a class="header-anchor" href="#遗忘的度量" aria-label="Permalink to &quot;遗忘的度量&quot;">​</a></h1><div class="epigraph"><p>训练损失升高不等于忘掉；拒答也不等于不可抽取。度量要分开：目标集上的可提取性、保留集上的效用、以及攻击换措辞后是否还在。</p><footer>—— 综合 Maini 等 TOFU（2024）、Li 等 WMDP（ICML 2024）、Eldan 与 Russinovich 的 Harry Potter 遗忘实验（2023）</footer></div><p>前几课已经在用「忘了」「还在」说话。<a href="/llm/continual-replay">回放</a>要旧任务回归；<a href="/llm/rmu-wmdp">RMU</a>要 WMDP 降、MMLU 留；<a href="/llm/rome-memit">ROME</a>要无关事实保持。本课把度量收成可写进配方的几栏，避免用单一准确率宣布成功。下一课<a href="/llm/negative-task-vector">负任务向量</a>仍用这套尺来验收算术遗忘。不发明新基准名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持续学习里的遗忘：任务 \\(T_i\\) 在学完 \\(T_{j\\gt i}\\) 之后的性能相对刚学完 \\(T_i\\) 时下降多少。隐私遗忘：攻击者能否从模型抽出 \\(D_f\\) 中的字符串或确认成员。能力遗忘：领域代理题是否仍会做。三种都叫 forgetting，曲线不可互换。用 MMLU 下降证明隐私遗忘，是用效用伤害冒充删除；用拒答率证明 WMDP 遗忘，是用接口冒充知识去掉。</p><p>Eldan 与 Russinovich 删除《哈利·波特》相关完成：表面问「霍格沃茨」会糊，换别名或补全诗句仍可能漏。度量必须含<strong>改写攻击集</strong>，否则只测了训练时见过的探针。</p><p><span class="marginnote">直觉类比：改写攻击就像通缉犯换了个发型——你只按原照片（原始探针）设卡，他换张脸就过去了。测遗忘不能只考原句，还得考同义改写、翻译、补全前缀这些变体，否则量到的只是「模型背没背过你的考题」。</span></p><h3 id="对照模型几乎总是缺的" tabindex="-1">对照模型几乎总是缺的 <a class="header-anchor" href="#对照模型几乎总是缺的" aria-label="Permalink to &quot;对照模型几乎总是缺的&quot;">​</a></h3><p>TOFU 的优点是虚构传记，可与从未见过该传记的模型比。真实预训练数据没有「从未见过莎士比亚」的对照。只能用：抽取长度、成员推断 AUC、释义一致率、以及效用下限。不要报告「与精确遗忘只差 1%」除非真有对照。</p><p><span class="marginnote">成员推断（Shokri 等的攻击传统）在 LLM 上不稳定，但仍应作为一栏：有的方法降低填空却提高成员可分性，或相反。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一份遗忘卡，最少四栏：</p><ol><li><strong>目标失败</strong>：在 \\(D_f\\) 探针上，准确率 / 精确抽取率 / WMDP 分，应下降。含原文、释义、翻译、补全前缀。</li><li><strong>效用</strong>：声明的 \\(D_r\\) 与通用基准，相对遗忘前的相对下降上限（例如 2%）。</li><li><strong>流畅与格式</strong>：在<a href="/llm/chat-template">chat template</a> 下是否仍能对话，而不是进入乱码。乱码是破坏，不是遗忘。</li><li><strong>攻击残余</strong>：Best-of-N、角色扮演、把答案藏在代码注释里等你实际会面对的套取。只选与威胁模型相关的，但至少一类非原探针。</li></ol><p>持续学习另加：<strong>平均准确率</strong>与<strong>向后迁移</strong>（旧任务变化）、<strong>向前迁移</strong>（新任务是否受益）。报表不要只给平均值。</p><p><span class="marginnote">数字实例：「效用相对下降上限 2%」怎么读——若遗忘前 MMLU 是 70%，遗忘后不得低于 68.6%。没有这条硬线，很多方法靠「把模型整个调坏」也能让目标集分数掉到零，但那种「删除」毫无产品意义。</span></p>',15)),(r(),n(s,null,{default:e(()=>[o(l,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%9B%AE%E6%A0%87%E6%8E%A2%E9%92%88%20%2B%20%E6%94%B9%E5%86%99%22%5D%20--%3E%20DEC%5B%22%E5%8F%AF%E6%8F%90%E5%8F%96%E6%80%A7%22%5D%0A%20%20R%5B%22%E4%BF%9D%E7%95%99%E4%BB%BB%E5%8A%A1%20%2B%20%E9%80%9A%E7%94%A8%22%5D%20--%3E%20UTIL%5B%22%E6%95%88%E7%94%A8%22%5D%0A%20%20A%5B%22%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%E6%94%BB%E5%87%BB%22%5D%20--%3E%20RES%5B%22%E6%AE%8B%E4%BD%99%22%5D%0A%20%20DEC%20--%3E%20CARD%5B%22%E9%81%97%E5%BF%98%E5%8D%A1%22%5D%0A%20%20UTIL%20--%3E%20CARD%0A%20%20RES%20--%3E%20CARD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"比较方法时用同一张卡。RMU、梯度上升、负任务向量、拒答 SFT 会在四栏上呈现不同轮廓：拒答常是 1 好、4 差；打乱权重常是 1 好、2–3 差。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[E("「损失升高」只说明 \\(D_f\\) 上的平均 NLL 变差。模型仍可能用低熵的错误完成（改写成反事实）或把概率质量从原文挪到同义改写上——抽取失败、知识还在。故目标栏要生成式抽取，不只闭卷准确率。效用栏防止把模型推到随机初始化。攻击栏防止度量过拟合探针分布，这与 SFT 过拟合"),t("a",{href:"/llm/instruction-data-lineage"},"谱系"),E("同构：你优化哪张表，哪张表就好看。")],-1)),(r(),n(s,null,{default:e(()=>[o(l,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%BD%E9%97%AE%E4%B8%80%E4%B8%AA%E5%B7%B2%E5%88%A0%E9%99%A4%E7%9A%84%E4%BA%8B%E5%AE%9E%22%5D%20--%3E%20A%5B%22%E6%8B%92%E7%AD%94%EF%BC%9A%E6%8E%A5%E5%8F%A3%E6%8C%A1%E4%BD%8F%EF%BC%8C%E7%9F%A5%E8%AF%86%E8%BF%98%E5%9C%A8%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E8%BE%93%E5%87%BA%E4%B9%B1%E7%A0%81%EF%BC%9A%E6%A8%A1%E5%9E%8B%E8%A2%AB%E7%A0%B4%E5%9D%8F%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E7%9C%9F%E9%81%97%E5%BF%98%EF%BC%9A%E5%8E%9F%E6%96%87%2F%E6%94%B9%E5%86%99%2F%E6%88%90%E5%91%98%E6%8E%A8%E6%96%AD%E9%83%BD%E6%8A%BD%E4%B8%8D%E5%87%BA%22%5D%0A%20%20A%20--%3E%20F1%5B%22%E6%94%B9%E5%86%99%E6%94%BB%E5%87%BB%E4%B8%80%E6%88%B3%E5%B0%B1%E6%BC%8F%EF%BC%8C%E6%94%BB%E5%87%BB%E6%AE%8B%E4%BD%99%E6%A0%8F%E4%B8%8D%E5%8F%8A%E6%A0%BC%22%5D%0A%20%20B%20--%3E%20F2%5B%22%E6%B5%81%E7%95%85%E6%A0%BC%E5%BC%8F%E6%A0%8F%E4%B8%8D%E5%8F%8A%E6%A0%BC%22%5D%0A%20%20C%20--%3E%20OK%5B%22%E7%9B%AE%E6%A0%87%E5%A4%B1%E8%B4%A5%20%2B%20%E6%95%88%E7%94%A8%E4%BF%9D%E7%95%99%20%3D%20%E5%90%88%E6%A0%BC%E8%BD%AE%E5%BB%93%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">常见误区：把「训练损失升高」当成遗忘完成的证据。损失只是平均值，模型完全可能把概率从原句挪到同义改写上——闭卷考看着掉了，换种问法仍能把原文抽出来。所以遗忘卡要求生成式抽取，而不只看选择题分数。</span></p><p>ROME 的局部性测试是遗忘卡在事实编辑上的特例：目标 / 邻近 / 流畅。应复用结构，换内容。</p><p><span class="marginnote">LoRA 卸载后四栏全回到基座，说明「遗忘」只存在于适配器。若合规要求针对基座，卡必须在卸载后测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有单一标量可以排序所有遗忘方法。产品选定威胁模型后，对四栏做阈值约束，再在约束内优化计算。公开论文的数字依赖其探针；迁移到内部 \\(D_f\\) 必须重做卡。不要用本课指标去「证明」监管意义上的删除完成。下一课的任务算术在卡上往往表现为：目标任务掉、邻近任务若方向重叠也会掉，效用栏要写清哪些算 \\(D_r\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持续学习遗忘、隐私抽取、能力代理是三种度量，不可互相替代。</li><li>遗忘卡至少含：目标失败（含改写）、效用、流畅格式、攻击残余。</li><li>拒答与乱码都不是合格遗忘。</li><li>无对照模型时不要声称接近精确遗忘。</li><li>适配器方法须声明卸载后是否仍测。</li><li>出处：Maini 等，TOFU，2024；Li 等，WMDP，2024；Eldan 与 Russinovich，2023；ROME 的局部性评测结构。</li></ul>',7))])}const u=B(d,[["render",m]]);export{_ as __pageData,u as default};
